/**
 * Signs local release builds (`expo run:android --variant release`,
 * `./gradlew bundleRelease`) with your Google Play upload key.
 *
 * `android/` is generated by `expo prebuild` and wiped by `--clean`, so the
 * signing config cannot be hand-edited there. This plugin re-injects it on
 * every prebuild. The key itself never enters the repo: its path and passwords
 * come from Gradle properties, normally in ~/.gradle/gradle.properties:
 *
 *   COHESIVE_UPLOAD_STORE_FILE=C:/Users/you/keys/cohesive-upload.keystore
 *   COHESIVE_UPLOAD_STORE_PASSWORD=...
 *   COHESIVE_UPLOAD_KEY_ALIAS=upload
 *   COHESIVE_UPLOAD_KEY_PASSWORD=...
 *
 * Without those properties the release build falls back to the debug key, so
 * `expo run:android --variant release` still works for testing on a device.
 * EAS Build ignores all this and signs with the key it manages.
 */
const { withAppBuildGradle } = require('expo/config-plugins');

const MARK = '// @cohesive-colors release signing';

const SIGNING = `
        ${MARK}
        release {
            if (project.hasProperty('COHESIVE_UPLOAD_STORE_FILE')) {
                storeFile file(COHESIVE_UPLOAD_STORE_FILE)
                storePassword COHESIVE_UPLOAD_STORE_PASSWORD
                keyAlias COHESIVE_UPLOAD_KEY_ALIAS
                keyPassword COHESIVE_UPLOAD_KEY_PASSWORD
            }
        }`;

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (cfg) => {
    let src = cfg.modResults.contents;
    if (src.includes(MARK)) return cfg;

    // 1. Add a `release` signing config next to the generated `debug` one.
    src = src.replace(/signingConfigs\s*\{\s*\n(\s*)debug\s*\{[\s\S]*?\n\1\}/, (block) => `${block}${SIGNING}`);

    // 2. Point the release build type at it when the upload key is configured.
    src = src.replace(
      /(release\s*\{[^}]*?)signingConfig signingConfigs\.debug/,
      `$1signingConfig project.hasProperty('COHESIVE_UPLOAD_STORE_FILE') ? signingConfigs.release : signingConfigs.debug`,
    );

    if (!src.includes(MARK) || !src.includes('signingConfigs.release')) {
      throw new Error('withReleaseSigning: android/app/build.gradle layout changed, update the plugin.');
    }
    cfg.modResults.contents = src;
    return cfg;
  });
};
